import{G as e,H as t,J as n,K as r,_t as i,at as a,lt as o,n as s}from"./chunks/framework.CZI4dhmU.js";import{nt as c}from"./chunks/assets.DeBnt35C.js";var l=JSON.parse(`{"title":"协程","description":"","frontmatter":{},"headers":[],"relativePath":"go/basic/advanced/goroutine.md","filePath":"go/basic/advanced/goroutine.md"}`),u={name:`go/basic/advanced/goroutine.md`};function d(s,l,u,d,f,p){let m=o(`DrawioViewer`),h=o(`ClientOnly`);return a(),e(`div`,null,[l[1]||=r(`<h1 id="协程" tabindex="-1">协程 <a class="header-anchor" href="#协程" aria-label="Permalink to “协程”">​</a></h1><p>是轻量级的执行单元，由 <code>Go</code>运行时（而非操作系统）管理，是 <code>Go</code> 并发编程的核心特性。</p><h2 id="系统运行单元" tabindex="-1">系统运行单元 <a class="header-anchor" href="#系统运行单元" aria-label="Permalink to “系统运行单元”">​</a></h2><h3 id="程序-program" tabindex="-1">程序(program) <a class="header-anchor" href="#程序-program" aria-label="Permalink to “程序(program)”">​</a></h3><p>是为完成特定任务、用某种语言编写的一组指令的集合，是一段静态的代码。</p><h3 id="进程-process" tabindex="-1">进程(process) <a class="header-anchor" href="#进程-process" aria-label="Permalink to “进程(process)”">​</a></h3><ul><li>进程是操作系统资源分配的基本单位，是一个正在运行的程序实例，拥有独立的内存空间、文件描述符、寄存器状态等系统资源。</li><li>进程间相互独立，通信需要通过 IPC（如管道、信号、共享内存等），开销较大。</li><li>由操作系统内核调度，切换成本高（需保存 / 恢复整个进程的上下文）。</li><li>一个程序可以启动多个进程（如多进程服务），但资源消耗高。</li></ul><h3 id="线程-thread" tabindex="-1">线程(thread) <a class="header-anchor" href="#线程-thread" aria-label="Permalink to “线程(thread)”">​</a></h3><ul><li>线程是进程内的执行单元，是操作系统调度的基本单位，共享所属进程的内存空间和资源，但有独立的栈和寄存器。</li><li>线程属于进程，一个进程可包含多个线程（多线程），线程间通信通过共享内存，比进程通信高效。</li><li>由操作系统内核调度（内核级线程），切换成本中等（需保存 / 恢复线程上下文，但共享进程资源）。</li><li>线程数量有限（受系统内存和内核限制），过多线程会导致调度效率下降。</li></ul><h3 id="协程-goroutine" tabindex="-1">协程(goroutine) <a class="header-anchor" href="#协程-goroutine" aria-label="Permalink to “协程(goroutine)”">​</a></h3><p>协程是一种用户态的轻量级线程，由 Go 运行时管理，比线程更轻量级，切换成本低。</p><h2 id="gmp-调度模型" tabindex="-1">GMP 调度模型 <a class="header-anchor" href="#gmp-调度模型" aria-label="Permalink to “GMP 调度模型”">​</a></h2>`,12),t(`p`,null,[n(h,null,{default:i(()=>[n(m,{page:`0`,title:``,edit:``,"dark-mode":`auto`,pages:``,highlight:``,nav:``,resize:``,height:`600px`,width:`100%`},{default:i(()=>[...l[0]||=[t(`img`,{src:c,alt:``},null,-1)]]),_:1})]),_:1})]),l[2]||=r(`<h2 id="运行是调度" tabindex="-1">运行是调度 <a class="header-anchor" href="#运行是调度" aria-label="Permalink to “运行是调度”">​</a></h2><ul><li>协程不由操作系统内核调度，而是由 Go 运行时的 GMP 调度模型 管理 <ul><li><code>G：Goroutine</code> 表示一个协程，是 <code>Go</code> 语言并发的基本单元。</li><li><code>M：Machine</code> 内核线程，绑定操作系统线程，真正跑代码。</li><li><code>P：Processor</code> 表示 “逻辑处理器”，是连接 <code>G</code> 和 <code>M</code> 的中间层，负责管理 <code>G</code> 的调度队列。</li></ul></li></ul><h2 id="调度流程" tabindex="-1">调度流程 <a class="header-anchor" href="#调度流程" aria-label="Permalink to “调度流程”">​</a></h2><h3 id="g的创建与入队" tabindex="-1"><code>G</code>的创建与入队 <a class="header-anchor" href="#g的创建与入队" aria-label="Permalink to “G的创建与入队”">​</a></h3><ul><li>当使用 <code>go</code> 关键字创建 <code>G</code> 时，<code>G</code> 会被加入当前 <code>P</code> 的本地运行队列（LRQ）。若 LRQ 满（默认容量 256），则会被转移到全局运行队列（GRQ）。</li></ul><h3 id="m-绑定-p-执行-g" tabindex="-1"><code>M</code> 绑定 <code>P</code> 执行 <code>G</code> <a class="header-anchor" href="#m-绑定-p-执行-g" aria-label="Permalink to “M 绑定 P 执行 G”">​</a></h3><ul><li><code>M</code> 启动后，会从 <code>P</code>的<code>LRQ</code>中获取<code>G</code> 并执行。</li><li>若<code>LRQ</code> 为空，<code>P</code> 会先尝试从 <code>GRQ</code> 中 “拉” 一批 <code>G</code>（通常是 <code>GRQ</code> 一半）到 <code>LRQ</code>，再执行。</li><li>若<code>GRQ</code> 也为空，<code>P</code> 会从其他 <code>P</code> 的 <code>LRQ</code> 中 “拉” 取 <code>G</code>（负载均衡，通常偷取对方一半的 <code>G</code>），避免自身 <code>M</code> 空闲。</li></ul><h3 id="g-的阻塞与唤醒" tabindex="-1"><code>G</code> 的阻塞与唤醒 <a class="header-anchor" href="#g-的阻塞与唤醒" aria-label="Permalink to “G 的阻塞与唤醒”">​</a></h3><ul><li>当 <code>G</code> 执行阻塞操作（如 channel 通信、time.Sleep、锁等待、系统调用等）： <ul><li>若阻塞在 <code>Go</code> 运行时内部（如 channel 或 sync.Mutex），<code>G</code> 会被标记为阻塞状态，从 <code>P</code> 的 <code>LRQ</code> 移除，<code>M</code> 会继续从 <code>LRQ</code> 中获取其他 <code>G</code> 执行（此时 <code>G</code> 不会阻塞 <code>M</code>）。</li><li>若阻塞在系统调用（如网络 I/O、文件读写），<code>M</code> 会暂时与 <code>P</code> 解绑，进入休眠状态；当系统调用完成后，<code>G</code> 会被重新加入某个 <code>P</code> 的 <code>LRQ</code> 或 <code>GRQ</code>，等待再次被调度。</li></ul></li></ul><h2 id="gomaxprocs" tabindex="-1">GOMAXPROCS <a class="header-anchor" href="#gomaxprocs" aria-label="Permalink to “GOMAXPROCS”">​</a></h2><ul><li><code>GOMAXPROCS</code> 控制 <code>P</code> 的数量，直接决定了程序的最大并行度（同一时间最多有 <code>GOMAXPROCS</code> 个 <code>G</code> 被执行）。</li><li>默认值为 <code>CPU</code> 核心数（可通过 runtime.NumCPU() 查看），通常无需修改。</li></ul>`,11)])}var f=s(u,[[`render`,d]]);export{l as __pageData,f as default};